SetColumns(0);SetQuitOnError(true);SetNthreads(1);Alarm(30);root:="work/deg10/continuation_20261031b/M3N18/";a:=eval Read(root cat "split_hecke_framed_arithmetic.txt");G:=AbelianGroup(a[3]);assert Invariants(G) eq a[3] and &and[G!v eq G!0:v in a[4]];cc:=[G!v:v in a[5]];extra:=[G!v:v in a[7]];Z:=FreeAbelianGroup(24+#extra);h:=hom<Z->G|cc cat extra>;GG:=Image(h);H:=sub<GG|[GG!v:v in cc]>;K:=GG;b:=eval Read(root cat "inert5_framed_arithmetic.m");assert b[3..8]eq a[3..8];
